CREATE POLICY "Authenticated users upload CREST media" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'crest-media' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admins read CREST media" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'crest-media' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admins update CREST media" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'crest-media' AND public.has_role(auth.uid(),'admin')) WITH CHECK (bucket_id = 'crest-media' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admins delete CREST media" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'crest-media' AND public.has_role(auth.uid(),'admin'));